// ── Pull data from all upstream nodes ──────────────────────────────
const metaRaw    = $('Windsor — Meta Spend').all()[0].json;
const googleRaw  = $('Windsor — Google Ads Spend').all()[0].json;
const shopifyTotal   = $('Shopify — Total Sales').all()[0].json;
const shopifyProds   = $('Shopify — Product Split').all();
const dateInfo   = $('Set Yesterday Date').all()[0].json;

// ── Meta ────────────────────────────────────────────────────────────
const metaData   = Array.isArray(metaRaw) ? metaRaw[0] : (metaRaw.data ? metaRaw.data[0] : metaRaw);
const metaSpend  = parseFloat(metaData?.spend || 0);
const metaRoasRaw = metaData?.purchase_roas;
const metaRoas   = Array.isArray(metaRoasRaw)
  ? parseFloat(metaRoasRaw[0]?.value || 0)
  : parseFloat(metaRoasRaw || 0);
const metaConvValue = metaSpend * metaRoas;

// ── Google Ads ───────────────────────────────────────────────────────
const googleData = Array.isArray(googleRaw) ? googleRaw[0] : (googleRaw.data ? googleRaw.data[0] : googleRaw);
const googleSpend = parseFloat(googleData?.spend || 0);
const googleConvValue = parseFloat(googleData?.conversions_value || 0);
const googleRoas = googleSpend > 0 ? googleConvValue / googleSpend : 0;

// ── Blended ──────────────────────────────────────────────────────────
const totalSpend     = metaSpend + googleSpend;
const totalConvValue = metaConvValue + googleConvValue;
const blendedRoas    = totalSpend > 0 ? totalConvValue / totalSpend : 0;

// ── Shopify Revenue ──────────────────────────────────────────────────
const shopifyRows = shopifyTotal?.shopifyqlQuery?.tableData?.unformattedData?.rowData || [];
const totalRevenue = shopifyRows.length > 0 ? parseFloat(shopifyRows[0][0] || 0) : 0;
const totalOrders  = shopifyRows.length > 0 ? parseInt(shopifyRows[0][1] || 0) : 0;
const grossSales   = shopifyRows.length > 0 ? parseFloat(shopifyRows[0][2] || 0) : 0;

// ── Product Split ─────────────────────────────────────────────────────
const prodRows = shopifyProds[0]?.json?.shopifyqlQuery?.tableData?.unformattedData?.rowData || [];
const productLines = prodRows
  .filter(r => r[0] && r[0].trim() && parseFloat(r[1]) > 0)
  .map(r => ({
    name: r[0].replace('NG EarSafe ', '').replace('NG x Wehear ', ''),
    gross: parseFloat(r[1]),
    net: parseFloat(r[2]),
    orders: parseInt(r[3])
  }))
  .sort((a, b) => b.gross - a.gross);

// ── Format currency ──────────────────────────────────────────────────
const fmt = (n) => '₹' + Math.round(n).toLocaleString('en-IN');
const fmtR = (n) => n.toFixed(2) + 'x';

// ── Build product HTML table rows ────────────────────────────────────
const productRowsHtml = productLines.length > 0
  ? productLines.map(p =>
      `<tr><td style="padding:6px 12px;border-bottom:1px solid #f0f0f0;">${p.name}</td>
       <td style="padding:6px 12px;border-bottom:1px solid #f0f0f0;text-align:right;font-weight:600;">${fmt(p.gross)}</td>
       <td style="padding:6px 12px;border-bottom:1px solid #f0f0f0;text-align:right;color:#666;">${p.orders} orders</td></tr>`
    ).join('')
  : '<tr><td colspan="3" style="padding:12px;color:#999;text-align:center;">No sales data yet for yesterday</td></tr>';

// ── Build email HTML ──────────────────────────────────────────────────
const html = `
<!DOCTYPE html><html><body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif;background:#f5f5f5;margin:0;padding:20px;">
<div style="max-width:600px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);">

  <!-- Header -->
  <div style="background:#102442;padding:24px 28px;">
    <h1 style="color:#fff;margin:0;font-size:20px;font-weight:700;">NG EarSafe — Daily Report</h1>
    <p style="color:#7eb3d4;margin:4px 0 0;font-size:13px;">${dateInfo.displayDate}</p>
  </div>

  <!-- Revenue Block -->
  <div style="padding:24px 28px 16px;border-bottom:2px solid #f0f4f8;">
    <h2 style="color:#102442;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin:0 0 16px;">💰 Revenue</h2>
    <div style="display:flex;gap:24px;margin-bottom:20px;">
      <div style="flex:1;background:#f0f8ff;border-radius:8px;padding:16px;">
        <div style="font-size:11px;color:#666;text-transform:uppercase;letter-spacing:0.5px;">Total Revenue</div>
        <div style="font-size:26px;font-weight:700;color:#102442;margin-top:4px;">${fmt(totalRevenue)}</div>
      </div>
      <div style="flex:1;background:#f0f8ff;border-radius:8px;padding:16px;">
        <div style="font-size:11px;color:#666;text-transform:uppercase;letter-spacing:0.5px;">Orders</div>
        <div style="font-size:26px;font-weight:700;color:#102442;margin-top:4px;">${totalOrders}</div>
      </div>
    </div>

    <!-- Product Split -->
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#f8fafc;">
          <th style="padding:8px 12px;text-align:left;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">Product</th>
          <th style="padding:8px 12px;text-align:right;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">Revenue</th>
          <th style="padding:8px 12px;text-align:right;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">Orders</th>
        </tr>
      </thead>
      <tbody>${productRowsHtml}</tbody>
    </table>
  </div>

  <!-- Ad Spend Block -->
  <div style="padding:24px 28px;">
    <h2 style="color:#102442;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin:0 0 16px;">📊 Ad Performance</h2>
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead>
        <tr style="background:#f8fafc;">
          <th style="padding:8px 12px;text-align:left;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">Channel</th>
          <th style="padding:8px 12px;text-align:right;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">Spend</th>
          <th style="padding:8px 12px;text-align:right;color:#666;font-weight:600;font-size:11px;text-transform:uppercase;">ROAS</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;"><span style="display:inline-block;width:8px;height:8px;background:#1877f2;border-radius:2px;margin-right:6px;"></span>Meta Ads</td>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;text-align:right;font-weight:600;">${fmt(metaSpend)}</td>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;text-align:right;color:${metaRoas >= 2 ? '#16a34a' : '#dc2626'};font-weight:600;">${fmtR(metaRoas)}</td>
        </tr>
        <tr>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;"><span style="display:inline-block;width:8px;height:8px;background:#4285f4;border-radius:2px;margin-right:6px;"></span>Google Ads</td>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;text-align:right;font-weight:600;">${fmt(googleSpend)}</td>
          <td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;text-align:right;color:${googleRoas >= 2 ? '#16a34a' : '#dc2626'};font-weight:600;">${fmtR(googleRoas)}</td>
        </tr>
        <tr style="background:#f0f4f8;">
          <td style="padding:12px;font-weight:700;color:#102442;">⚡ Blended Total</td>
          <td style="padding:12px;text-align:right;font-weight:700;color:#102442;">${fmt(totalSpend)}</td>
          <td style="padding:12px;text-align:right;font-weight:700;font-size:16px;color:${blendedRoas >= 2 ? '#16a34a' : '#dc2626'};">${fmtR(blendedRoas)}</td>
        </tr>
      </tbody>
    </table>
  </div>

  <!-- Footer -->
  <div style="background:#f8fafc;padding:16px 28px;text-align:center;">
    <p style="color:#999;font-size:11px;margin:0;">Auto-generated by NG EarSafe Growth Stack · Data: Shopify + Windsor.ai</p>
  </div>
</div>
</body></html>`;

return [{ json: { html, subject: `NG EarSafe Report — ${dateInfo.displayDate} | Rev: ${fmt(totalRevenue)} | Blended ROAS: ${fmtR(blendedRoas)}` } }];
